css:
:root{--bg:#f5efe2;--paper:#fffdf7;--ink:#1e1b16;--muted:#6b6254;--line:#d9cfbf;--accent:#8a5a21;--accent2:#c68b36;--green:#496a49;--green2:#72916d;--dark:#21180f;--soft:#e9dcc4;--shell:#b87b32}
*{box-sizing:border-box} html{scroll-behavior:smooth} body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.5} a{color:inherit} button{font:inherit}
.wrap{width:min(1180px,calc(100% - 32px));margin:auto}
.hero{padding:86px 0 56px;border-bottom:1px solid var(--line);background:linear-gradient(180deg,#efe3ce 0%,var(--bg) 100%)}
.eyebrow{font-size:.78rem;font-weight:850;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin-bottom:16px}
h1{font-size:clamp(3.5rem,9vw,7.5rem);line-height:.88;letter-spacing:-.068em;max-width:970px;margin:0 0 28px} .lead{font-size:clamp(1.15rem,2.6vw,1.55rem);max-width:840px;color:#423b31;margin:0} .hero-note{margin-top:22px;color:var(--muted);font-size:.92rem}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:38px 0 0} .stat{background:rgba(255,253,247,.76);border:1px solid var(--line);border-radius:18px;padding:22px} .num{font-weight:930;font-size:clamp(2rem,4vw,3.2rem);letter-spacing:-.05em;line-height:1;color:var(--dark)} .label{font-size:.92rem;color:var(--muted);margin-top:10px}
section{padding:64px 0;border-bottom:1px solid var(--line)} h2{font-size:clamp(2.1rem,4.5vw,3.8rem);line-height:.98;letter-spacing:-.05em;margin:0 0 20px} h3{letter-spacing:-.02em} .section-lead{max-width:760px;font-size:1.08rem;color:#4b4338;margin:0 0 34px}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px} .card{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:24px;min-height:0} .crop{font-weight:850;font-size:1.4rem;margin-bottom:10px} .value{font-size:2rem;font-weight:930;letter-spacing:-.04em;color:var(--accent)} .small{font-size:.92rem;color:var(--muted);margin-top:8px} .region{font-size:.8rem;text-transform:uppercase;letter-spacing:.12em;font-weight:850;color:var(--green);margin-bottom:7px}
.coproduct{border-top:1px solid var(--line);margin-top:18px;padding-top:16px;display:grid;gap:5px;font-size:.9rem} .coproduct b{color:var(--shell)} .coproduct span{color:#51483c}
.map-shell{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.85fr);gap:20px;align-items:stretch} .map-card{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:18px;position:relative} .map-controls{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px} .map-filter{border:1px solid var(--line);background:#f8f3e8;color:var(--ink);border-radius:999px;padding:8px 12px;cursor:pointer;font-size:.88rem} .map-filter.active{background:var(--dark);color:#fff;border-color:var(--dark)} .map-filter:focus-visible{outline:3px solid #d9b873;outline-offset:2px} .map-wrap{position:relative} #nut-map{display:block;width:100%;height:auto} .state{fill:#e5dfd2;stroke:#fffdf7;stroke-width:1.15;vector-effect:non-scaling-stroke;cursor:pointer;transition:fill .18s,opacity .18s,stroke .18s} .state:hover,.state:focus{stroke:var(--dark);stroke-width:2} .state.has-data{fill:#bca47d} .state.level-1{fill:#d7c5a4} .state.level-2{fill:#c5a477} .state.level-3{fill:#ac8150} .state.level-4{fill:#8f632e} .state.level-5{fill:#5f3f1e} .state.dim{opacity:.22} .state.selected{stroke:#17110b;stroke-width:3;opacity:1} .inset-label{font-size:14px;fill:#746a5b;font-weight:700}
.map-tooltip{position:absolute;pointer-events:none;background:#19130e;color:#fff;padding:8px 10px;border-radius:8px;font-size:.78rem;transform:translate(10px,-6px);display:none;max-width:220px;z-index:3}
.map-detail{background:var(--dark);color:#fff7ea;border-radius:22px;padding:26px;min-height:100%} .map-detail .muted{color:#ccbfa9} .map-detail h3{font-size:2rem;margin:4px 0 4px;letter-spacing:-.04em} .detail-value{font-size:2.7rem;font-weight:900;color:#efd29c;letter-spacing:-.05em;margin:0 0 14px} .detail-list{display:grid;gap:12px;margin-top:18px} .detail-crop{border-top:1px solid rgba(255,255,255,.16);padding-top:12px} .detail-crop strong{display:flex;justify-content:space-between;gap:12px} .detail-crop p{margin:6px 0 0;color:#d8cbb7;font-size:.88rem} .detail-note{border-top:1px solid rgba(255,255,255,.16);margin-top:18px;padding-top:16px;font-size:.9rem;color:#d8cbb7} .detail-source{display:inline-block;margin-top:16px;color:#fff;text-underline-offset:3px}
.map-legend{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:10px;color:var(--muted);font-size:.8rem} .swatch{display:inline-block;width:13px;height:13px;border-radius:3px;margin-right:5px;vertical-align:-2px}
.split{display:grid;grid-template-columns:1.1fr .9fr;gap:34px;align-items:start} .quote{font-size:clamp(2rem,4.5vw,4rem);line-height:1.02;letter-spacing:-.05em;font-weight:900;margin:0} .panel{background:var(--dark);color:#fff8ea;border-radius:22px;padding:28px} .panel h3{font-size:1.1rem;margin:0 0 12px} .panel p{color:#d9cdbb;margin:0 0 18px} .route{display:grid;gap:12px;margin-top:18px} .route div{display:flex;justify-content:space-between;gap:18px;border-top:1px solid rgba(255,255,255,.16);padding-top:12px} .route b{color:#fff}
.poetry{background:#21180f;color:#fff7e7} .poetry .eyebrow{color:#d6aa68} .poetry h2{max-width:900px} .poetry-lead{font-family:Georgia,serif;font-size:clamp(1.35rem,2.6vw,2rem);line-height:1.45;color:#eadfce;max-width:930px;margin:0 0 42px} .ecos{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.16);border-radius:22px;overflow:hidden} .eco{background:#21180f;padding:28px} .eco .region{color:#d6aa68} .eco h3{font-family:Georgia,serif;font-size:1.8rem;margin:0 0 10px;font-weight:500} .eco p{margin:0;color:#d9cdbb} .eco .after{margin-top:16px;color:#f0cf97;font-size:.88rem}
.byproduct-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px} .bycard{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:22px} .byicon{font-size:2rem;line-height:1;margin-bottom:12px} .bycard h3{margin:0 0 8px;font-size:1.25rem} .bycard p{margin:0;color:#51483c;font-size:.92rem} .stage{display:inline-block;margin-top:14px;border:1px solid var(--line);border-radius:999px;padding:5px 9px;font-size:.74rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--green)}
.flow{margin-top:26px;display:grid;grid-template-columns:repeat(5,1fr);gap:10px;align-items:stretch} .flow > div{background:#e9dcc4;border:1px solid #d0bea0;border-radius:16px;padding:16px;font-size:.9rem} .flow b{display:block;margin-bottom:5px}
.trend{display:grid;grid-template-columns:repeat(3,1fr);gap:16px} .trend .card{min-height:220px} .bigword{font-size:2.55rem;font-weight:920;letter-spacing:-.05em;color:var(--green)} .callout{background:#dfc697;border:1px solid #c7a66b;border-radius:24px;padding:34px} .callout p{font-size:clamp(1.4rem,3vw,2.1rem);line-height:1.2;letter-spacing:-.025em;margin:0;font-weight:800} .fine{font-size:.82rem;color:var(--muted);max-width:930px}
.sources{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:24px} .source{background:var(--paper);border:1px solid var(--line);padding:18px;border-radius:14px;font-size:.92rem;text-decoration:none} .source:hover{border-color:#9f8359} .source small{display:block;color:var(--muted);margin-top:5px}

.source-row{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin-top:15px;font-size:.78rem;color:var(--muted)}
.source-row>span{font-weight:800;color:var(--muted)}
.source-chip,.cite-link{display:inline-flex;align-items:center;gap:4px;border:1px solid var(--line);background:#f7f1e5;border-radius:999px;padding:5px 9px;text-decoration:none;color:#5d492d;font-weight:760;line-height:1.2}
.source-chip:hover,.cite-link:hover{border-color:#9f8359;background:#efe3ce}
.cite-link{font-size:.76rem;margin-left:4px;vertical-align:1px;padding:3px 7px}
.industry-intro{display:flex;justify-content:space-between;gap:22px;align-items:end;margin-bottom:30px}.evidence-key{display:flex;flex-wrap:wrap;gap:7px;max-width:510px}.tag{display:inline-block;border-radius:999px;padding:4px 8px;font-size:.68rem;font-weight:900;letter-spacing:.07em;text-transform:uppercase;border:1px solid var(--line);white-space:nowrap}.tag.use{background:#e9f0e6;color:#345237;border-color:#b9c9b5}.tag.product{background:#f3e5c9;color:#6d491d;border-color:#dbc397}.tag.rd{background:#e8e7e3;color:#55514a;border-color:#c9c5bd}
.industry-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.industry-card{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:24px}.industry-card h3{font-size:1.55rem;margin:2px 0 7px}.chain{font-size:.86rem;font-weight:800;color:var(--green);margin-bottom:17px}.factory{background:#f6f0e4;border-radius:14px;padding:14px;margin-bottom:15px}.factory b{display:block;margin-bottom:4px}.factory p{margin:0;color:#51483c;font-size:.9rem}.stream-list{display:grid;gap:9px}.stream{display:grid;grid-template-columns:auto 1fr;gap:9px;align-items:start;font-size:.9rem}.stream p{margin:1px 0 0;color:#51483c}.industry-note{margin-top:24px;padding:18px 20px;border-left:4px solid var(--accent);background:#eee2cd;border-radius:0 14px 14px 0;color:#4d4234;font-size:.9rem}.method-box{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:24px;display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.method-box div{font-size:.9rem;color:#51483c}.method-box b{display:block;color:var(--ink);margin-bottom:4px}.claim{font-size:.9rem;color:#51483c;margin:0}.claim+.claim{margin-top:8px}
footer{padding:34px 0 54px;color:var(--muted);font-size:.85rem}
@media(max-width:980px){.stats,.grid,.trend,.byproduct-grid{grid-template-columns:repeat(2,1fr)}.industry-grid{grid-template-columns:1fr}.industry-intro{display:block}.evidence-key{margin-top:16px}.method-box{grid-template-columns:1fr}.map-shell,.split{grid-template-columns:1fr}.map-detail{min-height:0}.sources{grid-template-columns:1fr}.flow{grid-template-columns:repeat(2,1fr)}}
@media(max-width:620px){.hero{padding-top:54px}.stats,.grid,.trend,.byproduct-grid,.ecos{grid-template-columns:1fr}section{padding:48px 0}.wrap{width:min(100% - 22px,1180px)}.flow{grid-template-columns:1fr}.map-card{padding:10px}.map-controls{gap:6px}.map-filter{padding:7px 9px;font-size:.8rem}}

.source-details{margin-top:22px}.source-details>summary{cursor:pointer;font-weight:850;color:var(--accent);padding:12px 0}.source-details[open]>summary{margin-bottom:10px}.detail-note summary{cursor:pointer;color:#efd29c;font-weight:800}.detail-note[open] summary{margin-bottom:4px}

script:
const paths=[...document.querySelectorAll('.state')];
const filters=[...document.querySelectorAll('.map-filter')];
const detail=document.getElementById('map-detail');
const tooltip=document.getElementById('map-tooltip');
let activeCrop='All'; let selected='CA';
function money(m){ if(m>=1000) return '$'+(m/1000).toFixed(m>=10000?1:2)+'B'; return '$'+m.toFixed(m>=100?0:1)+'M'; }
function cropValue(code,crop){const d=stateData[code]; if(!d)return 0; if(crop==='All')return d.value; return d.crops.filter(x=>x.name===crop).reduce((s,x)=>s+x.value,0);}
function renderMap(){
 const vals=paths.map(p=>cropValue(p.dataset.state,activeCrop)).filter(v=>v>0); const max=Math.max(...vals,1);
 paths.forEach(p=>{const code=p.dataset.state,v=cropValue(code,activeCrop);p.classList.remove('has-data','level-1','level-2','level-3','level-4','level-5','dim','selected'); if(v>0){p.classList.add('has-data'); const ratio=v/max; const lvl=ratio>.55?5:ratio>.20?4:ratio>.07?3:ratio>.02?2:1; p.classList.add('level-'+lvl);} else if(activeCrop!=='All' && stateData[code]) p.classList.add('dim'); if(code===selected)p.classList.add('selected');});
}
function renderDetail(code){selected=code; const d=stateData[code]; if(!d){detail.innerHTML=`<div class="muted">${stateNames[code]||code}</div><h3>No current annual major-nut estimate</h3><div class="detail-note">This does not mean the state grows no nuts. It means it is not represented by a current annual estimate for the major crops used on this page. Smaller or specialty crops are better investigated through USDA Quick Stats and the Census of Agriculture.</div>`;renderMap();return;}
 const shown=activeCrop==='All'?d.crops:d.crops.filter(c=>c.name===activeCrop); const total=shown.reduce((s,c)=>s+c.value,0);
 const cropHtml=shown.map(c=>{const ev=cropEvidence[c.name];return `<div class="detail-crop"><strong><span>${c.name}</span><span>${money(c.value)}</span></strong><p>${c.production} · ${c.price} · ${c.acres}</p><p><b>Beyond the kernel:</b> ${c.byproducts}</p>${ev?`<a class="detail-source" style="margin-top:8px;font-size:.8rem" target="_blank" rel="noopener" href="${ev.url}">Byproduct evidence: ${ev.label} ↗</a>`:''}</div>`;}).join('');
 detail.innerHTML=`<div class="muted">${stateNames[code]}</div><h3>${activeCrop==='All'?'Nut economy':activeCrop}</h3><div class="detail-value">${money(total)}</div><p class="muted">${d.role}</p><div class="detail-list">${cropHtml}</div><details class="detail-note"><summary>Regional context</summary><div style="margin-top:10px">${d.ecosystem}</div></details><a class="detail-source" target="_blank" rel="noopener" href="${d.source}">USDA state source ↗</a>`;
 renderMap();
}
filters.forEach(b=>b.addEventListener('click',()=>{activeCrop=b.dataset.crop;filters.forEach(x=>x.classList.toggle('active',x===b)); const candidates=Object.keys(stateData).filter(c=>cropValue(c,activeCrop)>0).sort((a,b)=>cropValue(b,activeCrop)-cropValue(a,activeCrop)); if(candidates.length) selected=candidates[0]; renderDetail(selected);}));
paths.forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('aria-label',stateNames[p.dataset.state]||p.dataset.state);p.addEventListener('click',()=>renderDetail(p.dataset.state));p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderDetail(p.dataset.state);}});p.addEventListener('mousemove',e=>{const code=p.dataset.state,v=cropValue(code,activeCrop);tooltip.style.display='block';tooltip.style.left=e.offsetX+'px';tooltip.style.top=e.offsetY+'px';tooltip.textContent=(stateNames[code]||code)+(v>0?' · '+money(v):' · no current major-series value');});p.addEventListener('mouseleave',()=>tooltip.style.display='none');});
renderDetail('CA');
